local _, Private = ...
local L = Private.L

local _G = _G

-- Baganator profile
function Private:Setup_Baganator()
	if not Private.IsAddOnLoaded('Baganator') then Private:Print('Baganator ' .. L["is not installed or enabled."]) return end

	-- Disable ElvUI bags
	if Private.ElvUI then
		ElvUI[1].private.bags.enable = false
	end

	-- Global db
	local dev = Private.Addon.db.global.dev

	-- Profile name
	local name = (dev and 'Luckyone') or 'Luckyone ' .. Private.Version

	-- Profile string
	local importString = [[BGR!1!]]

	-- Profile import
	local API = _G.Baganator.API
	API.ImportString(importString, name)

	-- Single bag view for nonRetail
	-- Remove the Retail categories and item as well
	-- Baganator will rebuild defaults after our reload popup
	if not Private.isRetail then
		local profile = _G.BAGANATOR_CONFIG.Profiles[name]
		profile.bag_view_type = 'single'
		profile.automatic_categories_added = {}
		profile.category_default_import = 0
		profile.category_display_order = {}
		profile.category_hidden = {}
		profile.category_modifications = {}
		profile.category_section_toggled = {}
		profile.category_sections = {}
		profile.custom_categories = {}
	end

	Private:Print(L["Baganator profile has been set."])
end
